/** What a request is about. */
export const Resource: Readonly<{
    FS: "fs";
    FOLDER: "folder";
    EMAIL: "email";
    APPS: "apps";
    SUBDOMAINS: "subdomains";
    APP_DATA: "appData";
    APP_ROOT_DIR: "appRootDir";
    BACKGROUND_EVENTS: "backgroundEvents";
    KV_SHARE: "kvShare";
}>;
/** An access level. `WRITE` includes `READ`. */
export const Access: Readonly<{
    READ: "read";
    WRITE: "write";
}>;
/** The special folders a `folder` request can name. */
export const Folder: Readonly<{
    DESKTOP: "Desktop";
    DOCUMENTS: "Documents";
    PICTURES: "Pictures";
    VIDEOS: "Videos";
}>;
